import type { MockupKind } from "@/lib/projects";

/**
 * CSS-only device mockups (no image files needed). Replace the <Screen />
 * contents with real screenshots later, e.g. <Image fill className="object-cover" />.
 */
export default function Mockup({ kind, tint }: { kind: MockupKind; tint: string }) {
  if (kind === "laptop") return <Laptop tint={tint} />;

  if (kind === "mixed") {
    return (
      <div className="relative pb-[8%]">
        <Laptop tint={tint} className="w-[90%]" />
        <Phone tint={tint} className="absolute bottom-0 right-0 w-[27%] rotate-6" />
      </div>
    );
  }

  return (
    <div className="flex items-start justify-center gap-[5%]">
      <Phone tint={tint} className="w-[44%] -rotate-6" />
      <Phone tint={tint} className="mt-[16%] w-[44%] rotate-6" />
    </div>
  );
}

function Phone({ tint, className = "" }: { tint: string; className?: string }) {
  return (
    <div
      className={`aspect-[9/19] rounded-[18%/8.5%] bg-ink p-[5%] shadow-[0_18px_28px_-10px_rgba(0,0,0,0.45)] ${className}`}
    >
      <div className="relative h-full w-full overflow-hidden rounded-[14%/6.5%] bg-paper">
        <div className="absolute left-1/2 top-[2.5%] h-[3%] w-[30%] -translate-x-1/2 rounded-full bg-ink" />
        <Screen tint={tint} />
      </div>
    </div>
  );
}

function Laptop({ tint, className = "" }: { tint: string; className?: string }) {
  return (
    <div className={`w-full ${className}`}>
      <div className="aspect-[16/10] rounded-t-[5%] bg-ink p-[2.5%] shadow-[0_18px_28px_-12px_rgba(0,0,0,0.45)]">
        <div className="h-full w-full overflow-hidden rounded-[2%] bg-paper">
          <Screen tint={tint} wide />
        </div>
      </div>
      <div className="relative -mx-[6%] h-[0.6rem] rounded-b-xl bg-neutral-300">
        <div className="absolute left-1/2 top-0 h-1/2 w-[18%] -translate-x-1/2 rounded-b-md bg-neutral-400" />
      </div>
    </div>
  );
}

/** Abstract UI: nav bar, hero block, and a few content rows. */
function Screen({ tint, wide = false }: { tint: string; wide?: boolean }) {
  return (
    <div className={`flex h-full flex-col gap-[5%] ${wide ? "p-[5%]" : "px-[9%] pb-[9%] pt-[16%]"}`}>
      <div className="flex items-center justify-between">
        <div className="h-[0.35rem] w-1/3 rounded-full bg-ink/80" />
        <div className="h-[0.35rem] w-1/5 rounded-full bg-ink/20" />
      </div>
      <div className={`${wide ? "flex gap-[5%]" : ""} flex-1`}>
        <div className="h-full min-h-[30%] flex-1 rounded-md" style={{ background: tint, opacity: 0.85 }} />
        {wide && (
          <div className="flex w-[40%] flex-col justify-center gap-[10%]">
            <div className="h-[0.35rem] w-full rounded-full bg-ink/70" />
            <div className="h-[0.35rem] w-4/5 rounded-full bg-ink/20" />
            <div className="h-[0.35rem] w-3/5 rounded-full bg-ink/20" />
            <div className="h-[0.7rem] w-1/2 rounded-full" style={{ background: tint }} />
          </div>
        )}
      </div>
      <div className="grid grid-cols-2 gap-[6%]">
        <div className="aspect-square rounded-md bg-ink/10" />
        <div className="aspect-square rounded-md bg-ink/10" />
      </div>
    </div>
  );
}
